"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def monitor_flag_rate(events):
    """The flag rate of a list of transcripts. See SPEC.md section 1."""
    total = 0
    hits = 0
    for event in events:
        total += 1
        if event["flagged"] is True:
            hits += 1
    return hits / total if total else 0.0



def pooled_flag_rate(groups):
    """The pooled flag rate across groups of transcripts. See SPEC.md section 2."""
    total = 0
    hits = 0
    for events in groups.values():
        for event in events:
            total += 1
            if event["flagged"] is True:
                hits += 1
    return hits / total if total else 0.0



def flags_in_window(daily_counts, days):
    """Sum over a trailing window of daily counts. See SPEC.md section 3."""
    if days <= 0:
        return 0
    return sum(daily_counts[-days:])



def flag_rate_by_group(groups):
    """The flag rate of each group. See SPEC.md section 9."""
    return {
        name: (monitor_flag_rate(groups[name]) if groups[name] else None)
        for name in sorted(groups)
    }



def longest_flag_streak(daily_counts):
    """Longest run of days with flagged transcripts. See SPEC.md section 10."""
    best = 0
    cur = 0
    for count in daily_counts:
        if count > 0:
            cur += 1
            best = max(best, cur)
        else:
            cur = 0
    return best

"""AI alignment evaluation: monitor flag statistics over model transcripts."""


def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    for line_number, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        if line.lstrip().startswith("#"):
            continue

        parts = line.split(",")
        if len(parts) != 3:
            raise ValueError(f"line {line_number}: expected 3 fields")

        id_, day_text, flagged_text = (part.strip() for part in parts)

        try:
            day = int(day_text)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: invalid day") from exc

        if flagged_text == "1":
            flagged = True
        elif flagged_text == "0":
            flagged = False
        elif flagged_text == "":
            flagged = None
        else:
            raise ValueError(f"line {line_number}: invalid flagged")

        out.append({"id": id_, "day": day, "flagged": flagged})

    return out



def dedupe_transcripts(events):
    """Remove duplicate transcripts. See SPEC.md section 5."""
    deduped = {}
    for event in events:
        deduped[event["id"]] = event
    return sorted(deduped.values(), key=lambda event: (event["day"], event["id"]))



def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    if end_day < start_day:
        return []

    counts = [0] * (end_day - start_day + 1)
    for event in events:
        day = event["day"]
        if start_day <= day <= end_day and event["flagged"] is True:
            counts[day - start_day] += 1
    return counts

"""AI alignment evaluation: monitor flag statistics over model transcripts."""
from safety_evals.loader import daily_flag_counts
from safety_evals.metrics import flags_in_window, monitor_flag_rate, pooled_flag_rate



def monitor_summary(groups, days):
    """Summary of groups of transcripts. See SPEC.md section 7."""
    all_events = [event for events in groups.values() for event in events]
    if all_events:
        first_day = min(event["day"] for event in all_events)
        last_day = max(event["day"] for event in all_events)
        recent = flags_in_window(daily_flag_counts(all_events, first_day, last_day), days)
    else:
        recent = 0

    return {
        "rate": round(pooled_flag_rate(groups), 3),
        "recent": recent,
        "groups": sum(1 for events in groups.values() if events),
    }



def top_flagged_groups(groups, n):
    """The groups with the highest flag rate. See SPEC.md section 8."""
    ranked = sorted(
        (
            (name, monitor_flag_rate(events))
            for name, events in groups.items()
            if events
        ),
        key=lambda item: (-item[1], item[0]),
    )
    return [name for name, _ in ranked[:n]]

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups



def test_monitor_flag_rate_basic():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": False}]) == 0.5



def test_monitor_flag_rate_none_counts_as_not_flagged():
    events = [{"flagged": True}, {"flagged": None}, {"flagged": False}]
    assert monitor_flag_rate(events) == 1 / 3



def test_pooled_flag_rate_weights_by_transcript_and_ignores_empty_groups():
    groups = {
        "a": [{"flagged": True}, {"flagged": False}, {"flagged": False}],
        "b": [{"flagged": True}],
        "c": [],
    }
    assert pooled_flag_rate(groups) == 0.5



def test_flags_in_window_uses_last_n_entries():
    assert flags_in_window([1, 2, 3, 4], 2) == 7
    assert flags_in_window([1, 2, 3, 4], 0) == 0



def test_parse_transcript_log_one_line():
    assert parse_transcript_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "flagged": True}]



def test_parse_transcript_log_skips_comments_and_blanks_and_parses_none():
    lines = ["   ", "  # comment", " x1 , 3 , ", "x2,4,0"]
    assert parse_transcript_log(lines) == [
        {"id": "x1", "day": 3, "flagged": None},
        {"id": "x2", "day": 4, "flagged": False},
    ]



def test_parse_transcript_log_reports_original_line_number_on_error():
    lines = ["", "# comment", "x1,not-a-day,1"]
    try:
        parse_transcript_log(lines)
    except ValueError as exc:
        assert "line 3" in str(exc)
    else:
        raise AssertionError("expected ValueError")



def test_dedupe_transcripts_keeps_last_duplicate_id_and_sorts_result():
    events = [
        {"id": "b", "day": 3, "flagged": True},
        {"id": "a", "day": 2, "flagged": False},
        {"id": "b", "day": 1, "flagged": False},
    ]
    assert dedupe_transcripts(events) == [
        {"id": "b", "day": 1, "flagged": False},
        {"id": "a", "day": 2, "flagged": False},
    ]



def test_daily_flag_counts_covers_full_range_and_ignores_out_of_range():
    events = [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": 1, "flagged": False},
        {"id": "c", "day": 3, "flagged": True},
        {"id": "d", "day": 5, "flagged": True},
    ]
    assert daily_flag_counts(events, 1, 4) == [1, 0, 1, 0]
    assert daily_flag_counts(events, 4, 3) == []



def test_monitor_summary_basic():
    groups = {
        "g1": [
            {"id": "a", "day": 1, "flagged": True},
            {"id": "b", "day": 3, "flagged": False},
        ],
        "g2": [],
        "g3": [{"id": "c", "day": 2, "flagged": True}],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}



def test_top_flagged_groups_excludes_empty_groups_and_breaks_ties_by_name():
    groups = {
        "b": [{"flagged": True}, {"flagged": False}],
        "a": [{"flagged": True}, {"flagged": False}],
        "c": [{"flagged": True}],
        "d": [],
    }
    assert top_flagged_groups(groups, 3) == ["c", "a", "b"]



def test_flag_rate_by_group_sorts_keys_and_uses_none_for_empty_groups():
    groups = {
        "b": [{"flagged": True}, {"flagged": False}],
        "a": [],
    }
    result = flag_rate_by_group(groups)
    assert list(result.keys()) == ["a", "b"]
    assert result == {"a": None, "b": 0.5}



def test_longest_flag_streak_resets_on_zero_days():
    assert longest_flag_streak([1, 2, 0, 3]) == 2
    assert longest_flag_streak([]) == 0
